public void processErasureRequest(UUID userId) {
    // 1. Mark as inactive in RDBMS
    userRepository.markAsDeleted(userId);
    // 2. Publish deletion event to Kafka for downstream consumers
    eventPublisher.publish(new UserErasureEvent(userId));
    // 3. Crypto-shred: Delete the user's encryption key from Vault
    keyVault.deleteKeyForUser(userId);
    // 4. Cleanup local NIO cache files
    Path userCache = Paths.get("/data/cache/" + userId.toString());
    try {
        Files.walkFileTree(userCache, new SimpleFileVisitor<Path>() {
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                Files.delete(file);
                return FileVisitResult.CONTINUE;
            }
        });
    } catch (IOException e) {
        log.error("Failed to purge local cache for user: {}", userId, e);
    }
}
